// ─────────────────────────────────────────────────────────────────────────────
// CONFIG — preencha aqui ou use variáveis de ambiente do n8n
// ─────────────────────────────────────────────────────────────────────────────
const CONFIG = {
  mondayApiKey: $env.MONDAY_API_KEY || 'COLE_AQUI_SUA_CHAVE_DA_MONDAY',
  boardId: 18411840245,
  defaultGroupId: 'topics',
  prioritizedGroupId: 'priorizado',
  backlogGroupId: 'backlog',
  doneGroupId: 'concluido',
};

// ─────────────────────────────────────────────────────────────────────────────
// Normalizar payload do Supabase Database Webhook
// O body pode vir como body.record, body.new, ou body direto
// ─────────────────────────────────────────────────────────────────────────────
const body = $input.first().json.body || $input.first().json;
const ticket = body.record || body.new || body;

if (!ticket || !ticket.id) {
  throw new Error('Payload inválido: campo id não encontrado. Body recebido: ' + JSON.stringify(body));
}

// Verificar idempotência: se já foi sincronizado, não criar novamente
if (ticket.monday_item_id) {
  return [{
    json: {
      __skip: true,
      reason: 'Ticket já sincronizado com Monday',
      supabase_id: ticket.id,
      monday_item_id: ticket.monday_item_id,
    }
  }];
}

// ─────────────────────────────────────────────────────────────────────────────
// Mapeamento de categoria → tipo Monday
// ─────────────────────────────────────────────────────────────────────────────
const CATEGORY_MAP = {
  'Erro na plataforma': 'Bug',
  'Dúvida operacional': 'Doubt',
  'Configuração': 'Configuration',
  'Integração': 'Integration',
  'Automação': 'Automation',
  'Pagamentos': 'Payments',
  'Outro': 'Other',
  'Solicitação de guia': 'Guide',
};

// ─────────────────────────────────────────────────────────────────────────────
// Mapeamento de prioridade → label Monday
// ─────────────────────────────────────────────────────────────────────────────
const PRIORITY_MAP = {
  'Urgente': 'P0',
  'Alta': 'P1',
  'Média': 'P2',
  'Baixa': 'P3',
};

// Definir grupo com base na prioridade
function chooseGroup(priority) {
  if (priority === 'Urgente' || priority === 'Alta') return CONFIG.prioritizedGroupId;
  return CONFIG.defaultGroupId;
}

const isGuideRequest = ticket.category === 'Solicitação de guia';

return [{
  json: {
    CONFIG,
    ticket: {
      id: ticket.id,
      name: ticket.name || '',
      email: ticket.email || '',
      company: ticket.company || '',
      subject: ticket.subject || ticket.topic || 'Sem assunto',
      category: ticket.category || 'Outro',
      priority: ticket.priority || 'Baixa',
      description: ticket.description || '',
      status: ticket.status || 'novo',
      created_at: ticket.created_at || new Date().toISOString(),
    },
    mappedCategory: CATEGORY_MAP[ticket.category] || ticket.category || 'Other',
    mappedPriority: PRIORITY_MAP[ticket.priority] || ticket.priority || 'P3',
    groupId: isGuideRequest ? CONFIG.backlogGroupId : chooseGroup(ticket.priority),
    itemName: isGuideRequest
      ? 'Solicitação de guia: ' + (ticket.subject || ticket.topic || 'Sem assunto')
      : (ticket.subject || ticket.topic || 'Novo ticket'),
    isGuideRequest,
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// Tipos de colunas NÃO editáveis via API — NUNCA incluir em column_values
// ─────────────────────────────────────────────────────────────────────────────
const NON_EDITABLE_TYPES = new Set([
  'pulse-log',      // PulseLogColumn — causa o erro reportado
  'formula',
  'mirror',
  'dependency',
  'board-relation',
  'lookup',
  'auto-number',
  'creation-log',
  'last-updated',
  'button',
  'item-id',
  'progress',
  'subitems',
]);

// Nomes de colunas que indicam não-editável mesmo se o tipo não estiver na lista
const NON_EDITABLE_TITLE_PATTERNS = [
  /^atuali[zs]a[cç][aã]o/i,
  /^updates?$/i,
  /^log$/i,
  /^comentários?$/i,
  /^activity/i,
  /^pulse.?log/i,
];

function isNonEditable(col) {
  if (NON_EDITABLE_TYPES.has(col.type)) return true;
  return NON_EDITABLE_TITLE_PATTERNS.some(p => p.test(col.title));
}

// ─────────────────────────────────────────────────────────────────────────────
// Dados vindos dos nodes anteriores
// ─────────────────────────────────────────────────────────────────────────────
const prepareData = $node['Preparar payload e CONFIG'].json;
const { CONFIG, ticket, mappedCategory, mappedPriority, groupId, itemName } = prepareData;

const boardResponse = $input.first().json;
const errors = boardResponse.errors;
if (errors && errors.length > 0) {
  throw new Error('Monday API retornou erro ao buscar estrutura: ' + JSON.stringify(errors));
}

const board = boardResponse.data?.boards?.[0];
if (!board) {
  throw new Error('Board ' + CONFIG.boardId + ' não encontrado na Monday API.');
}

const columns = board.columns || [];
const editableColumns = columns.filter(c => !isNonEditable(c));

// ─────────────────────────────────────────────────────────────────────────────
// Utilitário: encontra coluna pelo título (case-insensitive, parcial)
// ─────────────────────────────────────────────────────────────────────────────
function findColumn(searchTitle) {
  const q = searchTitle.toLowerCase();
  return editableColumns.find(c =>
    c.title.toLowerCase() === q ||
    c.title.toLowerCase().includes(q) ||
    q.includes(c.title.toLowerCase())
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Montar column_values apenas com colunas editáveis encontradas
// ─────────────────────────────────────────────────────────────────────────────
const columnValues = {};

// Solicitante / Nome
const colName = findColumn('Solicitante Forms') || findColumn('Solicitante') || findColumn('Nome');
if (colName && ticket.name) {
  columnValues[colName.id] = ticket.name;
}

// E-mail
const colEmail = findColumn('E-mail solicitante') || findColumn('E-mail') || findColumn('email');
if (colEmail && ticket.email) {
  if (colEmail.type === 'email') {
    columnValues[colEmail.id] = { email: ticket.email, text: ticket.email };
  } else {
    columnValues[colEmail.id] = ticket.email;
  }
}

// Empresa
const colCompany = findColumn('Empresa Solicita') || findColumn('Empresa') || findColumn('company');
if (colCompany && ticket.company) {
  columnValues[colCompany.id] = ticket.company;
}

// Assunto
const colSubject = findColumn('Assunto Solicitaç') || findColumn('Assunto') || findColumn('subject');
if (colSubject && ticket.subject) {
  columnValues[colSubject.id] = ticket.subject;
}

// Tipo / Categoria
const colType = findColumn('Tipo') || findColumn('type');
if (colType && mappedCategory) {
  columnValues[colType.id] = { label: mappedCategory };
}

// Prioridade
const colPriority = findColumn('Priority') || findColumn('Prioridade');
if (colPriority && mappedPriority) {
  columnValues[colPriority.id] = { label: mappedPriority };
}

// Status inicial
const colStatus = findColumn('Status');
if (colStatus) {
  columnValues[colStatus.id] = { label: 'Need Info' };
}

// Project Status
const colProjectStatus = findColumn('Project Status');
if (colProjectStatus) {
  columnValues[colProjectStatus.id] = { label: 'Em Entrada' };
}

// Cliente (se existir)
const colClient = findColumn('Cliente');
if (colClient && ticket.company) {
  columnValues[colClient.id] = ticket.company;
}

// Log de colunas encontradas (para debug)
const columnLog = {
  total: columns.length,
  editable: editableColumns.length,
  skipped: columns.filter(c => isNonEditable(c)).map(c => ({ id: c.id, title: c.title, type: c.type })),
  mapped: Object.keys(columnValues),
};

return [{
  json: {
    CONFIG,
    ticket,
    groupId,
    itemName,
    columnValues,
    columnLog,
    boardId: CONFIG.boardId,
  }
}];

const response = $input.first().json;
const errors = response.errors;

if (errors && errors.length > 0) {
  // Montar mensagem de erro legível
  const readableErrors = errors.map(e => {
    const parts = [];
    if (e.message) parts.push(e.message);
    if (e.extensions?.code) parts.push('code: ' + e.extensions.code);
    if (e.extensions?.column_type) parts.push('column_type: ' + e.extensions.column_type);
    if (e.extensions?.column_id) parts.push('column_id: ' + e.extensions.column_id);
    if (e.path) parts.push('path: ' + e.path.join('.'));
    return parts.join(' | ');
  }).join('\n');

  throw new Error('Monday create_item falhou:\n' + readableErrors);
}

const item = response.data?.create_item;
if (!item || !item.id) {
  throw new Error('Monday create_item não retornou item válido: ' + JSON.stringify(response));
}

// Dados do node anterior
const buildData = $node['Montar item Monday'].json;

return [{
  json: {
    monday_item_id: item.id,
    monday_item_name: item.name,
    ticket: buildData.ticket,
    CONFIG: buildData.CONFIG,
  }
}];

// Handler de erro global
const errorMessage = $input.first()?.error?.message || $input.first()?.json?.error || 'Erro desconhecido';
const ticketId = $node['Preparar payload e CONFIG']?.json?.ticket?.id;

console.error('[n8n Monday Sync] Erro:', errorMessage, 'ticket_id:', ticketId);

// Tentar atualizar Supabase com status de erro
return [{
  json: {
    __error: true,
    error_message: errorMessage,
    ticket_id: ticketId,
    CONFIG: $node['Preparar payload e CONFIG']?.json?.CONFIG,
  }
}];
